// Original 2D blocking study. Background band members are unnamed, not unlocked cast.
export function musicSceneState(record){
 const role=record.choices?.[0]?.id??'vocal';
 const performed=record.choices?.some(c=>c.id==='perform');
 return {role:['vocal','bass','guitar'].includes(role)?role:'vocal',phase:performed?'performance':record.step===0?'setup':record.step===1?'practice':record.step===2?'together':'wrap',performed};
}
export function activityScene(record){
 if(record.postId!=='music-recruit')return physicalActivityScene(record);
 const {role,phase,performed}=musicSceneState(record);
 const label={setup:'마이크와 악기를 준비하는 합주실',practice:'파트를 연습하는 김태이와 부원들',together:'서로 신호를 보며 합주하는 부원들',performance:'노래와 연주를 이어가는 짧은 공연',wrap:'연습을 마무리하는 합주실'}[phase];
 const guitar=role!=='vocal';
 return `<div class="activity-tableau" data-phase="${phase}" data-role="${role}"><svg viewBox="0 0 900 650" role="img" aria-label="${label}" preserveAspectRatio="xMidYMid slice">
 <defs><linearGradient id="studio-wall" x2="0" y2="1"><stop stop-color="#263c4c"/><stop offset="1" stop-color="#121b2a"/></linearGradient><radialGradient id="studio-light"><stop stop-color="#f3d29c" stop-opacity=".38"/><stop offset="1" stop-color="#edb67b" stop-opacity="0"/></radialGradient></defs>
 <path fill="url(#studio-wall)" d="M0 0h900v650H0z"/><path fill="#b48161" opacity=".3" d="M0 425h900v225H0z"/>
 ${[40,210,380,550,720].map(x=>`<rect x="${x}" y="70" width="130" height="250" rx="6" fill="#152331" stroke="#49505a"/>`).join('')}
 <ellipse cx="450" cy="230" rx="400" ry="330" fill="url(#studio-light)"/><path d="M0 510l900 0M0 585h900M150 425L40 650M360 425l-25 225M580 425l50 225M790 425l100 225" stroke="#c6a17b" opacity=".2"/>
 <g class="band-drummer" stroke="#222838" stroke-width="8" stroke-linecap="round"><path d="M655 315v100m-18-35-40 62m74-62 45 62"/><ellipse cx="655" cy="275" rx="25" ry="29" fill="#d9b59a" stroke="none"/><path d="M630 270q0-48 46-18l7 20" fill="#37303a" stroke="none"/><path d="M625 313q30-20 60 0l12 55h-80" fill="#77857c" stroke="none"/><path d="m626 328-35 25m92-25 37 17" stroke="#d9b59a"/><path d="m590 353-25-42m155 34 18-40" stroke="#d6bd8e" stroke-width="4"/><circle cx="657" cy="425" r="58" fill="#364958" stroke="#b6b2a1"/><path d="M565 372h65v35h-65zM688 369h65v35h-65z" fill="#557080" stroke="#b6b2a1" stroke-width="3"/><path d="M555 310v147m190-155v155" stroke="#b6b2a1" stroke-width="3"/><ellipse cx="555" cy="310" rx="42" ry="6" fill="#c4a364" stroke="none"/><ellipse cx="745" cy="302" rx="42" ry="6" fill="#c4a364" stroke="none"/></g>
 <g class="band-keyboard"><ellipse cx="206" cy="280" rx="26" ry="30" fill="#cfaa91"/><path d="M178 279q-1-55 51-16l5 26-15-24-36 19" fill="#292b35"/><path d="M173 319q32-20 63 0l19 84h-92z" fill="#897b86"/><path d="m180 337-8 44 42 4m17-46 14 40 27 5" stroke="#cfaa91" stroke-width="13" fill="none" stroke-linecap="round"/><path d="M185 401v102m40-102 14 102" stroke="#303746" stroke-width="20"/><path d="M133 385h155v23H133z" fill="#e3dfd0" stroke="#263542" stroke-width="7"/><path d="m150 412 122 94m0-94-122 94" stroke="#a9adb0" stroke-width="6"/>${[150,170,190,210,230,250,270].map(x=>`<path d="M${x} 385v13" stroke="#283240" stroke-width="6"/>`).join('')}</g>
 <g class="activity-taei"><ellipse cx="447" cy="527" rx="82" ry="12" fill="#111824" opacity=".5"/><path d="m425 414-12 105m57-105 18 105" stroke="#26303c" stroke-width="25" stroke-linecap="round"/><path d="m401 518 22 1m55 0 24 1" stroke="#cdd3cf" stroke-width="14" stroke-linecap="round"/><path d="M407 301q40-22 80 0l15 119q-50 16-108 0z" fill="#344d5b" stroke="#99b8bb" stroke-width="2"/><path d="M420 303l24 35 29-35m-29 35v79" stroke="#bec6b7" fill="none" stroke-width="3"/><path d="M436 277v26q10 12 22 0v-26" fill="#dcbda5"/><ellipse cx="447" cy="253" rx="32" ry="39" fill="#e5c8b1"/><path d="M414 257q-15-53 27-54l35 10 12 34-23-19-8 21-10-20-25 34-1-21z" fill="#202733"/><path d="M429 257h9m18 0h9" stroke="#2b3037" stroke-width="3"/><circle cx="429" cy="265" r="1.6" fill="#3d3936"/><path d="M441 278q7 ${performed?'7':'2'} 15 0" fill="none" stroke="#9b6d65" stroke-width="2"/>
 ${guitar?`<path d="M413 313l80 93" stroke="#c1a16c" stroke-width="6"/><path d="M410 382q-30 16-7 44 17 16 36-4 20 2 23-20-7-25-28-15z" fill="${role==='bass'?'#b88c53':'#a65a47'}" stroke="#e1b88b" stroke-width="3"/><path d="m433 393 72-78" stroke="#d1b185" stroke-width="12"/><path d="m429 406 77-89" stroke="#ede4ca" stroke-width="2"/><path d="m405 326-23 45 38 24m66-68 7 21-13 11" fill="none" stroke="#dcbda5" stroke-width="13" stroke-linecap="round"/>`:`<path d="m407 325-15 53 29 12m65-64 19-29-20-19" fill="none" stroke="#dcbda5" stroke-width="14" stroke-linecap="round"/><path d="m483 280-17-14" stroke="#182637" stroke-width="9" stroke-linecap="round"/><ellipse cx="462" cy="263" rx="9" ry="7" fill="#c0c6bf"/><path d="M481 296q45 84 1 184t75 43" fill="none" stroke="#14202b" stroke-width="3"/>`}</g>
 <g fill="#efe4cd" font-family="sans-serif" font-size="15"><text x="44" y="42">예술동 · 대형 합주실</text><text x="44" y="610">${{setup:'준비',practice:'파트 연습',together:'호흡 맞추기',performance:'짧은 공연',wrap:'마무리'}[phase]} · ${{vocal:'VOCAL',bass:'BASS',guitar:'GUITAR'}[role]}</text></g></svg><span class="tableau-note">2D 활동 장면 시제품</span></div>`;
}

function activityFigure(x,y,{taei=false,color='#6f8894',arms='down',apron=false,box=false}={}){
 const skin=taei?'#e5c8b1':'#cfaa91';
 const gesture={down:'M-28 78l-15 66m71-66 15 66',reach:'M-28 78l-22 35 42 6m36-41 21 28-39 15',high:'M-28 78l-16-32 23-23m49 55 18-32-23-23',carry:'M-28 78l-10 30 18 12m48-42 10 30-18 12'}[arms];
 return `<g class="physical-actor ${taei?'physical-taei':''}" transform="translate(${x} ${y})"><ellipse cy="225" rx="55" ry="8" fill="#0e1d2b" opacity=".24"/><path d="M-17 144l-8 73m42-73 12 73" stroke="#293644" stroke-width="19" stroke-linecap="round"/><path d="M-31 220h18m30 0h20" stroke="#e4e5d6" stroke-width="10" stroke-linecap="round"/><path d="M-29 67q29-13 58 0l10 86h-78z" fill="${color}" stroke="#bdd1ce" stroke-width="2"/>${apron?'<path d="M-17 71h34l10 78h-54z" fill="#d6c3a3"/><path d="M-14 112h28v20h-28z" fill="none" stroke="#8b816f"/>':''}<path d="M-8 45v20q8 9 16 0V45" fill="${skin}"/><ellipse cy="30" rx="23" ry="29" fill="${skin}"/><path d="M-24 34q-12-40 23-39l23 9 10 27-22-16-8 15-6-17-17 23-3-17z" fill="#202a35"/><path d="M-13 31h6m14 0h6" stroke="#273440" stroke-width="2"/>${taei?'<circle cx="-13" cy="37" r="1.3" fill="#453c38"/>':''}<path d="M-5 47q6 4 12 0" fill="none" stroke="#a27264" stroke-width="2"/><path d="${gesture}" fill="none" stroke="${skin}" stroke-width="11" stroke-linecap="round"/>${box?'<path d="M-39 94h78v51h-78z" fill="#bf9b6d" stroke="#e2ca9d" stroke-width="2"/><path d="M-5 94h10v51H-5z" fill="#e2d3ab"/><path d="M-26 117h14m-14 8h20" stroke="#69584a" stroke-width="2"/>':''}</g>`;
}
export function physicalActivityScene(record){
 const kind=record.postId==='basketball-open'?'basketball':record.postId==='cooking-open'?'cooking':'carry';
 const phase=record.step===0?'setup':record.step===1?'action':record.step===2?'finish':'wrap';
 const a=record.actionState??{},last=record.choices?.at(-1)?.id;
 let scene='',label='';
 if(kind==='basketball'){
  label='실내 코트에서 공을 주고받는 학생들';
  scene=`<path fill="#526d75" d="M0 0h900v650H0z"/><path d="M0 340h900v310H0z" fill="#bc9669"/><g fill="none" stroke="#f5e3bd" stroke-width="4"><path d="M0 390h900M450 340v310"/><ellipse cx="450" cy="505" rx="100" ry="62"/><path d="M650 650V440h200v210M650 470q-110 80 0 150"/></g><path d="M730 100h105v70H730z" fill="#d5dfd5" stroke="#29404d" stroke-width="7"/><path d="M761 127h43v29h-43zM792 171v140" fill="none" stroke="#526d75" stroke-width="4"/><ellipse cx="781" cy="178" rx="27" ry="7" fill="none" stroke="#dd7448" stroke-width="5"/><path d="m756 181 8 28h34l9-28m-43 0 8 28m16-28-8 28" fill="none" stroke="#eee7d5" stroke-width="2"/>
  ${activityFigure(360,230,{taei:true,color:'#355567',arms:last==='shoot'?'high':last==='pass'?'reach':'down'})}${activityFigure(540,235,{color:'#99877d',arms:'reach'})}${activityFigure(150,270,{color:'#607d74',arms:'reach'})}
  <g class="activity-ball" transform="translate(${last==='shoot'?680:last==='pass'?210:310} ${last==='shoot'?185:385})"><circle r="20" fill="#d88e4b" stroke="#754e34" stroke-width="2"/><path d="M-20 0h40M0-20v40M-15-14q25 10 29 28" fill="none" stroke="#754e34" stroke-width="2"/></g><rect x="42" y="225" width="175" height="40" rx="8" fill="#173541"/><text x="56" y="251" fill="#f1e6cf" font-size="18">공격 ${a.round??0}/3 · 득점 ${a.scored??0}</text>`;
 }else if(kind==='cooking'){
  label='앞치마를 두르고 냄비를 함께 살피는 조리 체험';
  scene=`<path fill="#adbdb5" d="M0 0h900v650H0z"/><path d="M0 400h900v250H0z" fill="#788f8d"/><g stroke="#d6e0d6" opacity=".5">${[60,140,220,300,380].map(y=>`<path d="M0 ${y}h900"/>`).join('')}${[80,180,280,380,480,580,680,780].map(x=>`<path d="M${x} 0v400"/>`).join('')}</g><path d="M430 80h240l40 70H390z" fill="#5a7378"/><path d="M470 0h160v80H470z" fill="#6f8789"/>
  ${activityFigure(350,215,{taei:true,color:'#355567',apron:true,arms:phase==='setup'?'down':'reach'})}${activityFigure(610,215,{color:'#947b72',apron:true,arms:'reach'})}
  <path d="M170 405h590v135H170z" fill="#536c71" stroke="#cad1c5" stroke-width="7"/><path d="M190 540v65m550-65v65" stroke="#435c63" stroke-width="12"/><path d="M220 416h140v55H220z" fill="#c3a277"/><path d="m237 433 50 0m-46 15 35 0m35-15 15 18" stroke="#a6b96a" stroke-width="9"/><path d="M410 421h180v53H410z" fill="#243b46"/><path d="M455 386h90v53q-45 17-90 0z" fill="#bec9bf" stroke="#384f59" stroke-width="4"/><path d="M454 404h-17m109 0h17" stroke="#bec9bf" stroke-width="8"/><ellipse cx="500" cy="387" rx="43" ry="8" fill="#d3b580"/>${phase!=='setup'?'<g class="activity-steam" fill="none" stroke="#f1eee0" stroke-width="5" opacity=".7"><path d="M476 369q-15-16 0-31t0-29m25 60q-15-16 0-31t0-29m25 60q-15-16 0-31t0-29"/></g>':''}<ellipse cx="648" cy="440" rx="31" ry="14" fill="#dfdbca"/><path d="m360 394 48-33" stroke="#d3d6cb" stroke-width="7"/>`;
 }else{
  label='상자를 함께 들고 통로를 지나 물품을 정리하는 운반 조';
  scene=`<path fill="#8b9d9f" d="M0 0h900v650H0z"/><path d="M0 390h900v260H0z" fill="#b9ac91"/><path d="M80 145h160v250H80z" fill="#425e69"/><path d="M100 170h120v170H100z" fill="#829b9a"/><path d="M680 180v330m150-330v330M680 260h150m-150 100h150m-150 100h150" fill="none" stroke="#405964" stroke-width="13"/>
  ${activityFigure(400,235,{taei:true,color:'#355567',arms:phase==='wrap'?'down':'carry',box:phase!=='wrap'})}${activityFigure(550,230,{color:'#8d7c86',arms:phase==='wrap'?'down':'carry',box:a.method==='solo'&&phase!=='wrap'})}
  ${[0,1,2].map(i=>`<g transform="translate(${phase==='wrap'?700:210+i*70} ${phase==='wrap'?408-i*73:440})"><path d="M0 0h65v55H0z" fill="#bf9b6d" stroke="#e2ca9d" stroke-width="2"/><path d="M28 0h9v55h-9z" fill="#e2d3ab"/><path d="M8 27h13m-13 8h23" stroke="#69584a" stroke-width="2"/></g>`).join('')}
  ${a.obstacle==='chair'&&a.route!=='clear'&&phase!=='wrap'?'<path d="M105 450v-60h55v60m-60 0h70m-62 0v55m52-55v55" fill="none" stroke="#5d7077" stroke-width="10"/>':''}<path d="M280 555h360m-18-12 18 12-18 12" fill="none" stroke="#f0e4c8" stroke-width="5"/>`;
 }
 return `<div class="activity-tableau physical-tableau" data-kind="${kind}" data-phase="${phase}"><svg viewBox="0 0 900 650" role="img" aria-label="${label}" preserveAspectRatio="xMidYMid meet">${scene}</svg><span class="tableau-note">2D 활동 장면 시제품</span></div>`;
}
